import {
  ChangeDetectionStrategy,
  ChangeDetectorRef,
  Component,
} from '@angular/core';
import {
  presentListData,
  presentSetupData,
  teamResponce,
} from '../../../interfaces/presentsetup';
import { PresentsetupService } from '../../../services/presentsetup/presentsetup.service';
import { ActivatedRoute } from '@angular/router';
import { CommonfunctionService } from '../../../../core/utility/commonfunction.service';
import { FormsModule } from '@angular/forms';
import { TeamuserComponent } from '../teamuser/teamuser.component';
import { ButtonComponent } from '../../../../shared/components/button/button.component';
import { GroupComponent } from '../group/group.component';
import { LocationStrategy } from '@angular/common';
import { HeaderService } from '../../../../core/services/header/header.service';
import { UserPermissionService } from '../../../../shared/services/user-permission/user-permission.service';

@Component({
  selector: 'app-form',
  standalone: true,
  changeDetection: ChangeDetectionStrategy.OnPush,
  imports: [FormsModule, TeamuserComponent, ButtonComponent, GroupComponent],
  templateUrl: './form.component.html',
  styleUrl: './form.component.scss',
})
export class FormComponent {
  nCaseid: string;
  presentData: presentSetupData;
  teamlist: teamResponce[];

  presetationList: presentListData[] = [];

  selectedUser: string[] = [];
  cName: string = '';
  type: string = 'F';
  constructor(
    private readonly PSservice: PresentsetupService,
    private cm: CommonfunctionService,
    private route: ActivatedRoute,
    private cdr: ChangeDetectorRef,
    private location: LocationStrategy,
    private hs: HeaderService,
    private userPermissions: UserPermissionService
  ) {
    var params = this.route.snapshot.params;

    params = JSON.parse(decodeURIComponent(params['id']));
    this.nCaseid = params && params['id'] ? params['id'] : null;
    this.type = params && params['type'] ? params['type'] : 'F';
    hs.nCaseid = this.nCaseid;

    // disable window history 
    history.pushState(null, null, window.location.href);
    this.location.onPopState(() => {
      history.pushState(null, null, window.location.href);
    });

    userPermissions.userPermissionList(this.nCaseid);

  }

  async ngOnInit() {
    this.presentData = await this.PSservice.getRvalue(this.nCaseid);
    try {
      if (this.presentData?.jUsers?.length) {
        this.selectedUser = [...this.presentData.jUsers];
        this.cName = this.presentData.cName;
      }
    } catch (error) {
      console.error(error);
    }

    this.cdr.detectChanges();
  }

  async ChooseFile() {
    if (!this.selectedUser?.length || !this.cName) return;
    await this.PSservice.setRvalue({
      nCaseid: this.nCaseid,
      jUsers: this.selectedUser,
      cName: this.cName,
    });
    if (this.type == 'F') {
      this.cm.gotoUrl('/present/choose-docs', { id: this.nCaseid });
    } else if (this.type == 'W') {
      // this.cm.gotoUrl('/present/witness-docs', { id: this.nCaseid });
      this.cm.gotoUrl('/present/createWitness',
        { id: this.nCaseid }
      );
    } else if (this.type == 'C') {
      // this.cm.gotoUrl('/present/witness-docs', { id: this.nCaseid });     
      this.cm.gotoUrl('/present/core-case', { id: this.nCaseid });
    }
  }
}
